class Solution:
    def minWindow(self, s: str, t: str) -> str:
        need = {}
        for c in t:
            need[c] = need.get(c, 0) + 1
        missing = len(t)
        best_start, best_len = 0, len(s) + 1
        l = 0
        for h, c in enumerate(s):
            if need.get(c, 0) > 0:
                missing -= 1
            need[c] = need.get(c, 0) - 1
            while missing == 0:
                if h - l + 1 < best_len:
                    best_start, best_len = l, h - l + 1
                d = s[l]
                need[d] += 1
                if need[d] > 0:
                    missing += 1
                l += 1
        return "" if best_len > len(s) else s[best_start:best_start + best_len]
